const fs=require('node:fs'),os=require('node:os'),path=require('node:path'),request=require('supertest');
const {createAuthenticatedActionApp}=require('./authenticated-app.cjs');
const {createApp}=require('../../../server');
let directory,cookie;
beforeEach(async()=>{directory=fs.mkdtempSync(path.join(os.tmpdir(),'dianliang-api-limit-'));const seed=createAuthenticatedActionApp({dataDir:directory,reviewDirectory:path.join(directory,'assets'),rateLimitEnabled:false}).app,r=await request(seed).post('/api/register').send({name:'limit-reader',password:'test-only-2026'});expect(r.status).toBe(201);cookie=r.headers['set-cookie'].map(v=>v.split(';')[0]).join('; ')});
afterEach(()=>{vi.useRealTimers();if(!path.resolve(directory).startsWith(path.resolve(os.tmpdir())+path.sep))throw Error('Unexpected fixture');fs.rmSync(directory,{recursive:true,force:true})});
function limited(extra={}){return createAuthenticatedActionApp({dataDir:directory,reviewDirectory:path.join(directory,'assets'),rateLimitEnabled:true,rateLimitMax:3,rateLimitWindowMs:1000,...extra}).app}
it('counts one logical request across legacy and review APIs without an extra session-probe request',async()=>{
 const app=limited();expect((await request(app).get('/api/me').set('Cookie',cookie)).status).toBe(200);expect((await request(app).get('/api/action-state').set('Cookie',cookie)).status).toBe(200);expect((await request(app).get('/api/review-public-tutorials').set('Cookie',cookie)).status).toBe(200);const denied=await request(app).post('/api/review-tutorial-discussions/missing-tutorial').set('Cookie',cookie).send({text:'must not write'});expect(denied.status).toBe(429);expect(denied.body.code).toBe('RATE_LIMITED');expect(fs.existsSync(path.join(directory,'tutorial-discussions'))).toBe(false);expect((await request(app).get('/api/me').set('Cookie',cookie)).status).toBe(429);
});
it('keeps rate-disabled fixtures functional and rejects foreign origins before consuming the request allowance',async()=>{
 const app=limited();expect((await request(app).get('/api/action-state').set('Cookie',cookie).set('Origin','https://foreign.example')).status).toBe(403);for(const route of ['/api/action-state','/api/review-received-replies','/api/me'])expect((await request(app).get(route).set('Cookie',cookie)).status).toBe(200);expect((await request(app).get('/api/review-owned-discussions').set('Cookie',cookie)).status).toBe(429);const off=limited({rateLimitEnabled:false});for(let i=0;i<5;i++)expect((await request(off).get('/api/review-owned-discussions').set('Cookie',cookie)).status).toBe(200);
});
it('ignores forged forwarded addresses when proxy trust is disabled and recovers after the configured window',async()=>{
 vi.useFakeTimers({toFake:['Date']});const app=limited();for(let i=0;i<3;i++)expect((await request(app).get('/api/action-state').set('Cookie',cookie).set('X-Forwarded-For','192.0.2.'+(i+1))).status).toBe(200);expect((await request(app).get('/api/action-state').set('Cookie',cookie).set('X-Forwarded-For','192.0.2.99')).status).toBe(429);vi.setSystemTime(Date.now()+1001);expect((await request(app).get('/api/action-state').set('Cookie',cookie)).status).toBe(200);
});
it('resolves only minimal authenticated identity with the original cookie semantics and does not mutate sessions',async()=>{
 const service=createApp({dataDir:directory,rateLimitEnabled:false}),before=fs.readFileSync(service.config.sessionsPath,'utf8'),req={get:()=>cookie},user=service.resolveSession(req);expect(Object.keys(user).sort()).toEqual(['id','name']);expect(user.name).toBe('limit-reader');expect(service.resolveSession({get:()=>undefined})).toBeNull();expect(service.resolveSession({get:()=> 'kht_session=forged'})).toBeNull();expect(fs.readFileSync(service.config.sessionsPath,'utf8')).toBe(before);const rows=JSON.parse(before);for(const token of Object.keys(rows))rows[token].createdAt='2000-01-01T00:00:00.000Z';fs.writeFileSync(service.config.sessionsPath,JSON.stringify(rows));const expired=fs.readFileSync(service.config.sessionsPath,'utf8');expect(service.resolveSession(req)).toBeNull();expect(fs.readFileSync(service.config.sessionsPath,'utf8')).toBe(expired);
});
it('matches the original sliding-window decisions through a long burst, expiry and clock corrections',()=>{
 vi.useFakeTimers({toFake:['Date']});const start=Date.now(),max=3,windowMs=1000,limiter=createApp({dataDir:directory,rateLimitEnabled:true,rateLimitMax:max,rateLimitWindowMs:windowMs}).limitApiRequest;let time=start,reference=[];for(let i=0;i<10000;i++){if(i%331===0)time+=1200;else if(i%77===0)time-=100;else time+=i%5===0?3:0;vi.setSystemTime(time);reference=reference.filter(at=>time-at<windowMs);reference.push(time);const expected=reference.length>max?429:200;let actual=200;limiter({ip:'192.0.2.1',socket:{}},{status(code){actual=code;return this},json(){}},()=>{});expect(actual).toBe(expected)}
});
it('preserves independent active-address windows while dormant addresses expire',()=>{
 vi.useFakeTimers({toFake:['Date']});const start=Date.now(),limiter=createApp({dataDir:directory,rateLimitEnabled:true,rateLimitMax:2,rateLimitWindowMs:1000}).limitApiRequest,call=ip=>{let result=200;limiter({ip,socket:{}},{status(code){result=code;return this},json(){}},()=>{});return result};for(let i=0;i<2000;i++){expect(call('192.0.2.'+i)).toBe(200)}expect(call('active')).toBe(200);expect(call('active')).toBe(200);expect(call('active')).toBe(429);vi.setSystemTime(start+1100);expect(call('active')).toBe(200);expect(call('192.0.2.0')).toBe(200);expect(call('active')).toBe(200);expect(call('active')).toBe(429);
});
it.each([['nonnumeric',{rateLimitMax:'not-a-number'}],['infinite',{rateLimitMax:Infinity}],['zero',{rateLimitMax:0}],['negative',{rateLimitMax:-1}],['fractional',{rateLimitMax:1.5}],['bad-window',{rateLimitWindowMs:'invalid'}],['zero-window',{rateLimitWindowMs:0}],['infinite-window',{rateLimitWindowMs:Infinity}]])('rejects enabled limiter configuration %s before recovering or changing stored data',(_name,options)=>{
 const journal=path.join(directory,'restore-journal.json'),bytes=JSON.stringify({format:'kht-restore/v1',entries:[{relative:'states/config-guard-proof.json',value:{shouldNotApply:true}}]});fs.writeFileSync(journal,bytes);expect(()=>createApp({dataDir:directory,rateLimitEnabled:true,rateLimitMax:3,rateLimitWindowMs:1000,...options})).toThrow(RangeError);expect(fs.readFileSync(journal,'utf8')).toBe(bytes);expect(fs.existsSync(path.join(directory,'states','config-guard-proof.json'))).toBe(false);
});
it('accepts numeric settings without changing their values and ignores unused limiter settings when explicitly disabled',async()=>{
 const valid=createApp({dataDir:directory,rateLimitEnabled:true,rateLimitMax:'3',rateLimitWindowMs:'1000'});expect(valid.config.rateLimitMax).toBe(3);expect(valid.config.rateLimitWindowMs).toBe(1000);const disabled=createApp({dataDir:directory,rateLimitEnabled:false,rateLimitMax:'invalid',rateLimitWindowMs:'invalid'});expect((await request(disabled.app).get('/api/me').set('Cookie',cookie)).status).toBe(200);
});
